function validSalesNumber(id,integer=false){const el=$(id),raw=el?.value??'';if(el?.validity?.badInput)return false;if(raw.trim()==='')return true;const value=Number(raw);return Number.isFinite(value)&&value>=0&&value<=1e12&&(!integer||Number.isSafeInteger(value))}
function knownTxRows(list=tx){const rows=new Map(),date=$('date').value,bk=businessKey($('business').value);for(const rec of getSaved().slice().sort((a,b)=>String(a.savedAt||'').localeCompare(String(b.savedAt||'')))){const loaded=historical?rec.id===historicalRecordId:(rec.date===date&&businessKey(rec.business)===bk);if(loaded)continue;for(const t of rec.tx||[])if(t?.id)rows.set(String(t.id),{t,date:rec.date||'',where:rec.business||'Saved day',recordId:rec.id})}for(const t of list||[])if(t?.id)rows.set(String(t.id),{t,date,where:historical?'Saved day':'Today'});return [...rows.values()]}
