function refundMutationError(before,next){const known=knownTxRows(next).map(x=>x.t),byId=new Map(known.map(t=>[String(t.id),t]));for(const old of before){if(TYPES[old.type]?.cat!=='sale'||!linkedSaleRefunds(old.id,null,before).length)continue;const replacement=next.find(t=>String(t.id)===String(old.id));if(!replacement)return 'This sale has linked refunds. Reverse those refunds before deleting the sale.';if(replacement.productId!==old.productId||replacement.type!==old.type||n(replacement.qty)!==n(old.qty)||Math.round(n(replacement.amount)*100)!==Math.round(n(old.amount)*100))return 'This sale has linked refunds. Reverse those refunds before changing its product, quantity, price or payment type.'}for(const t of next){if(TYPES[t.type]?.cat!=='refund'||!t.originalSaleId)continue;const old=before.find(x=>String(x.id)===String(t.id));if(old&&old.originalSaleId===t.originalSaleId&&n(old.qty)===n(t.qty)&&Math.round(n(old.amount)*100)===Math.round(n(t.amount)*100))continue;const source=byId.get(String(t.originalSaleId)),totals=refundSaleTotals(t.originalSaleId,null,next);if(!source||TYPES[source.type]?.cat!=='sale'||source.productId!==t.productId)return 'The original sale for this refund is no longer available.';if(totals.qty>n(source.qty)+.0001||totals.cents>Math.round(n(source.amount)*100))return 'This refund would exceed the quantity or amount of its original sale.'}return ''}
function retailCashOutViolation(list,opening=n($('openingCash').value)){let balance=n(opening);for(const t of list){const cashOut=t.type==='sale_cashout'?n(t.cashOut??t.changeReturned):0;if(cashOut>0&&cashOut>balance+.004)return{tx:t,available:Math.max(0,roundMoney(balance)),required:roundMoney(cashOut)};balance+=calc([t],{openingCash:0,posOpeningCash:0,posOpeningElectronic:0,openingDebt:0,openingSupplierPayable:0}).expectedCash}return null}
