function ensureHistoryIndex(){if(PERF.historyIndexRev===PERF.savedRev&&PERF.historyIndex)return PERF.historyIndex;const byProduct=new Map(),refundBySale=new Map();for(const r of getSaved()){for(const t of(r.tx||[])){if(t.productId){let a=byProduct.get(t.productId);if(!a)byProduct.set(t.productId,a=[]);a.push({t,date:r.date||'',where:r.business||'Saved day',recordId:r.id})}if(t.originalSaleId&&TYPES[t.type]?.cat==='refund')refundBySale.set(String(t.originalSaleId),(refundBySale.get(String(t.originalSaleId))||0)+n(t.qty))}}for(const a of byProduct.values())a.sort((x,y)=>String(y.t.ts||y.date).localeCompare(String(x.t.ts||x.date)));PERF.historyIndex={byProduct,refundBySale};PERF.historyIndexRev=PERF.savedRev;return PERF.historyIndex}
function saleSourceCandidates(productId){if(!productId)return[];return knownTxRows().filter(x=>x.t.productId===productId&&TYPES[x.t.type]?.cat==='sale').sort((a,b)=>String(b.t.ts||b.date).localeCompare(String(a.t.ts||a.date)))}
