function refundPricingRule(p){if(editIndex>=0){const old=tx[editIndex];if(old&&old.productId===p?.id&&TYPES[old.type]?.cat==='refund'&&Object.prototype.hasOwnProperty.call(old,'quantityPricingApplied'))return{sellingPrice:n(old.unitSellingPrice??old.unitPrice??p?.price),quantityPricingEnabled:!!old.quantityPricingEnabledAtSale,quantityPricingQuantity:n(old.quantityPricingQuantity),quantityPricingPrice:n(old.quantityPricingPrice)}}const src=findSaleSource($('refundSource')?.value);return src?ruleFromSaleRecord(src,p):p}

