function divLines(r){const L=['SALES BY DIVISION'];DIVS.forEach(d=>L.push(DIVLBL[d]+' sales: '+fmt(r.byDiv[d].sales)));if(r.byDiv.unassigned.sales)L.push('Unassigned sales: '+fmt(r.byDiv.unassigned.sales));L.push('Total sales: '+fmt(r.sales));L.push('');const sold=soldByDiv();DIVK.forEach(d=>{const v=Object.values(sold[d]);if(!v.length)return;L.push(DIVLBL[d].toUpperCase());v.forEach(x=>L.push(x.name+' — '+x.qty+' sold'));L.push('')});return L}
