function packQtyLabel(s){const x=physicalPackText(s);return'<div class="qtyDisplay"><div class="qtyMain">'+esc(x.main)+'</div>'+(x.sub?'<div class="qtySub">'+esc(x.sub)+'</div>':'')+'</div>'}
