function expiryInfo(s){const expiry=nearestExpiry(s)||s.expiryDate;if(!expiry)return{level:0,days:null,date:null,state:'normal'};const base=today(),baseMs=dateOnlyMs(base),exp=dateOnlyMs(expiry);if(baseMs==null||exp==null)return{level:0,days:null,date:expiry,state:'normal'};const days=Math.round((exp-baseMs)/86400000);if(days<0)return{level:4,days,date:expiry,state:'expired'};const one=addCalendarMonths(expiry,-1),three=addCalendarMonths(expiry,-3),six=addCalendarMonths(expiry,-6);if(one&&base>=one)return{level:3,days,date:expiry,state:'soon'};if(three&&base>=three)return{level:2,days,date:expiry,state:'approaching'};if(six&&base>=six)return{level:1,days,date:expiry,state:'upcoming'};return{level:0,days,date:expiry,state:'normal'}}
