function expiryLabel(s){const e=expiryInfo(s);if(e.level===4)return'<span class="badge expired">Expired · '+Math.abs(e.days)+'d ago</span>';if(e.level===3)return'<span class="badge expirySoon">'+(e.days===0?'Expires today':'Expires soon · '+e.days+'d')+'</span>';if(e.level===2)return'<span class="badge expiryApproaching">Expiry approaching · '+e.days+'d</span>';if(e.level===1)return'<span class="badge expiryUpcoming">Upcoming expiry · '+e.days+'d</span>';return''}
function addBatch(s,qty,cost,expiry,batchId=null,t=null){if(qty<=0)return null;if(t?.adjustmentBatchId){const existing=(s.batches||[]).find(b=>b.id===t.adjustmentBatchId);if(existing){existing.qty+=qty;return existing;}}const upp=Math.floor(n(s.unitsPerPack)),packMatch=!!s.packEnabled&&upp>0&&t?.packSelected&&Math.floor(n(t.unitsPerPackAtTx))===upp;const b=normalizeBatch({id:batchId||uid('b'),qty,costPrice:cost,expiryDate:expiry||null,packStateKnown:!!s.packEnabled&&upp>0,packUnitSize:upp,sealedPacks:packMatch?Math.max(0,Math.floor(n(t.packsEntered))):0,looseUnits:packMatch?Math.max(0,Math.floor(n(t.looseUnitsEntered))):Math.max(0,Math.floor(n(qty)))});s.batches=s.batches||[];s.batches.push(b);return b}
