function consumeBatches(s,qty,t=null){if(!Number.isFinite(qty)||qty<=0||((s.batches||[]).reduce((sum,b)=>sum+Math.max(0,n(b.qty)),0)+0.0001)<qty)return{ok:false,alloc:[]};let left=qty,alloc=[];const upp=Math.floor(n(s.unitsPerPack)),batches=(s.batches||[]).filter(b=>!t?.adjustmentBatchId||b.id===t.adjustmentBatchId).slice().sort(batchSort);for(const b of batches){if(left<=0)break;const take=Math.min(n(b.qty),left);if(take>0){b.qty-=take;left-=take;if(t?.packSelected)b.packStateKnown=false;else if(s.packEnabled&&upp>0)reduceKnownBatchLooseFirst(b,take,upp);alloc.push({batchId:b.id,qty:take,costPrice:n(b.costPrice),expiryDate:b.expiryDate||null,packStateKnown:!!b.packStateKnown,packUnitSize:n(b.packUnitSize),sealedPacks:n(b.sealedPacks),looseUnits:n(b.looseUnits)})}}s.batches=(s.batches||[]).filter(b=>n(b.qty)>0);return{ok:left<=.0001,alloc}}
