function ensureSupplierIndex(){if(PERF.supplierIndexRev===PERF.savedRev&&PERF.supplierIndex)return PERF.supplierIndex;const byBiz=new Map();for(const rec of getSaved()){const bk=businessKey(rec.business);let delta=0;for(const t of(rec.tx||[])){if(t.type==='purchase_credit')delta+=n(t.amount);else if(t.type==='supplier_pay_cash'||t.type==='supplier_pay_bank')delta-=n(t.amount)}let a=byBiz.get(bk);if(!a)byBiz.set(bk,a=[]);a.push({date:rec.date||'',delta})}for(const a of byBiz.values()){a.sort((x,y)=>x.date.localeCompare(y.date));let bal=0;for(const x of a){bal=Math.max(0,bal+x.delta);x.balanceAfter=bal}}PERF.supplierIndex=byBiz;PERF.supplierIndexRev=PERF.savedRev;return byBiz}
function supplierOpeningFor(date,business){if(!date)return 0;const a=ensureSupplierIndex().get(businessKey(business))||[];let lo=0,hi=a.length-1,ans=-1;while(lo<=hi){const m=(lo+hi)>>1;if(a[m].date<date){ans=m;lo=m+1}else hi=m-1}return ans>=0?n(a[ans].balanceAfter):0}
function recordCalc(rec){if(rec&&PERF.recordCalc.has(rec))return PERF.recordCalc.get(rec);const f={...(rec?.fields||{})};if(f.openingSupplierPayable==null)f.openingSupplierPayable=supplierOpeningFor(rec?.date,rec?.business);const c=calc(rec?.tx||[],f);if(rec)PERF.recordCalc.set(rec,c);return c}
function recordProductAgg(rec){if(rec&&PERF.recordProductAgg.has(rec))return PERF.recordProductAgg.get(rec);const out={};for(const t of(rec?.tx||[])){const cat=TYPES[t.type]?.cat;if(!t.productId||!['sale','refund'].includes(cat))continue;const k=t.productId,p=out[k]||(out[k]={units:0,sales:0,name:t.productName||t.note||t.productId,div:txDiv(t)});if(cat==='sale'){p.units+=n(t.qty);p.sales+=n(t.amount)}else{p.units-=n(t.qty);p.sales-=n(t.amount)}}if(rec)PERF.recordProductAgg.set(rec,out);return out}
function currentSupplierOpening(){return supplierOpeningFor($('date').value,$('business').value)}

function applyEffect(t,reverse=false,preserveCost=false){if(!t.productId||!n(t.qty))return true;const arr=getStock(),i=arr.findIndex(s=>s.id===t.productId);if(i<0)return false;const s=clone(arr[i]),q=n(t.qty),cat=TYPES[t.type]?.cat;if(!cat||!Number.isFinite(q)||q<=0)return false;if(!reverse&&['sale','adjustminus','damaged'].includes(cat)&&((s.batches||[]).reduce((sum,b)=>sum+Math.max(0,n(b.qty)),0)+0.0001)<q)return false;
 if(cat==='purchase'&&t.packSelected&&n(t.unitsPerPackAtTx)>0){const incoming=Math.floor(n(t.unitsPerPackAtTx));if(!s.packEnabled||Math.floor(n(s.unitsPerPack))!==incoming){s.packEnabled=true;s.unitsPerPack=incoming;s.sealedPacks=0;s.looseUnits=n(s.qty)}}
 if(!reverse){
  if(!t.physicalPackBefore)t.physicalPackBefore={packEnabled:!!s.packEnabled,unitsPerPack:n(s.unitsPerPack),sealedPacks:n(s.sealedPacks),looseUnits:n(s.looseUnits)};
  if(cat==='purchase'){const b=addBatch(s,q,n(t.unitPrice),t.batchExpiry||null,t.batchId||null,t);t.batchId=b?.id||null;s.currentCostPrice=n(t.unitPrice);s.currentCostSource='purchase';s.currentCostSourceTxId=t.id||null;if(t.sellingPriceAfter!=null){s.price=n(t.sellingPriceAfter);s.priceMode='manual';s.markupMode='custom';s.markupPercent=impliedMarkup(s.currentCostPrice,s.price);}else if(s.priceMode==='markup')s.price=priceFromMarkup(s.currentCostPrice,s.markupMode==='default'?divisionDefaultMarkup(divOf(s)):s.markupPercent);addPhysicalUnits(s,t,q)}
  else if(cat==='sale'||cat==='adjustminus'||cat==='damaged'){if(!reducePhysicalForTx(s,t,q))return false;const c=consumeBatches(s,q,t);if(!c.ok){s.packEnabled=!!t.physicalPackBefore.packEnabled;s.unitsPerPack=n(t.physicalPackBefore.unitsPerPack);s.sealedPacks=n(t.physicalPackBefore.sealedPacks);s.looseUnits=n(t.physicalPackBefore.looseUnits);return false}t.batchAllocations=c.alloc;if(cat==='sale'&&q>0&&!preserveCost)t.costSnapshot=c.alloc.reduce((a,x)=>a+n(x.qty)*n(x.costPrice),0)/q}
  else if(cat==='adjustplus'||(cat==='refund'&&t.returnToStock)){if(cat==='refund'&&Array.isArray(t.returnBatchAllocations)&&t.returnBatchAllocations.length){const ids=[];t.returnBatchAllocations.forEach((a,j)=>{const b=addBatch(s,n(a.qty),n(a.costPrice),a.expiryDate||null,t.returnBatchIds?.[j]||null);if(b)ids.push(b.id)});t.returnBatchIds=ids;t.batchId=ids[0]||null}else{const b=addBatch(s,q,n(t.costSnapshot??s.costPrice),t.batchExpiry||null,t.batchId||null,t);t.batchId=b?.id||null}if(cat==='adjustplus'&&n(t.currentCostAfter)>0){s.currentCostPrice=n(t.currentCostAfter);s.currentCostSource='manual';s.currentCostSourceTxId=t.id||null}if(t.sellingPriceAfter!=null){s.price=n(t.sellingPriceAfter);s.priceMode='manual';s.markupMode='custom';s.markupPercent=impliedMarkup(currentCost(s),s.price);}else if(s.priceMode==='markup')s.price=priceFromMarkup(currentCost(s),effectiveProductMarkup(s));addPhysicalUnits(s,t,q)}
 }else{
  if(cat==='purchase'||cat==='adjustplus'||(cat==='refund'&&t.returnToStock)){let left=q;s.batches=(s.batches||[]).map(b=>{if(left<=0)return b;if(cat==='refund'&&t.returnBatchIds?.length?!t.returnBatchIds.includes(b.id):(t.batchId&&b.id!==t.batchId))return b;const take=Math.min(n(b.qty),left);b.qty-=take;left-=take;return b}).filter(b=>n(b.qty)>0)}
  else if(cat==='sale'||cat==='adjustminus'||cat==='damaged')restoreAllocations(s,t.batchAllocations||[]);
  if(t.physicalPackBefore){s.packEnabled=!!t.physicalPackBefore.packEnabled;s.unitsPerPack=n(t.physicalPackBefore.unitsPerPack);s.sealedPacks=n(t.physicalPackBefore.sealedPacks);s.looseUnits=n(t.physicalPackBefore.looseUnits)}
 }
 recalcProduct(s);arr[i]=s;const oldCause=auditCause;auditCause={...oldCause,category:cat,type:cat==='purchase'?'Restock & price update':['adjustplus','adjustminus','damaged'].includes(cat)?(t.currentCostAfter!=null?'Stock receipt & price update':'Stock correction'):oldCause?.type,reason:t.party||oldCause?.reason||'',transactionId:t.id,source:t.marketPurchaseId?'Market Desk':oldCause?.source||'Stock',batchId:t.adjustmentBatchId||null};try{setStock(arr,[s.id]);}finally{auditCause=oldCause;}return true
}
function productMetaSnapshot(p){if(!p)return null;return{name:p.name,division:divOf(p),currentCostPrice:currentCost(p),price:n(p.price),markupMode:p.markupMode,markupPercent:p.markupPercent,priceMode:p.priceMode,quantityPricingEnabled:!!p.quantityPricingEnabled,quantityPricingQuantity:Math.max(0,Math.floor(n(p.quantityPricingQuantity))),quantityPricingPrice:Math.max(0,n(p.quantityPricingPrice)),lowThreshold:p.lowThreshold==null?null:n(p.lowThreshold),targetQty:n(p.targetQty),packEnabled:!!p.packEnabled,unitsPerPack:Math.max(0,Math.floor(n(p.unitsPerPack)))}}
function rebuildStockFromOpening(){const synced=SmartSync.rebuildStock();if(synced!==null)return synced;auditMuted++;try{const safety=clone(getStock()),currentById=new Map(safety.map(p=>[p.id,p])),replay=clone(tx);const baseline=normalizeStockArray(Object.values(openingStock||{})).map(x=>{const cur=currentById.get(x.id);if(cur){x.name=cur.name;x.division=divOf(cur);x.price=cur.price;x.markupMode=cur.markupMode;x.markupPercent=cur.markupPercent;x.priceMode=cur.priceMode;x.quantityPricingEnabled=!!cur.quantityPricingEnabled;x.quantityPricingQuantity=cur.quantityPricingQuantity;x.quantityPricingPrice=cur.quantityPricingPrice;x.lowThreshold=cur.lowThreshold;x.targetQty=cur.targetQty;x.packEnabled=!!cur.packEnabled;x.unitsPerPack=cur.unitsPerPack;if(cur.currentCostSource==='manual'){x.currentCostPrice=currentCost(cur);x.currentCostSource='manual';x.currentCostSourceTxId=null}}return recalcProduct(x)});setStock(baseline);for(const t of replay){delete t.batchAllocations;delete t.physicalPackBefore;if(!applyEffect(t,false,true)){setStock(safety);return false}}const final=getStock();for(const p of final){const cur=currentById.get(p.id);if(!cur)continue;const source=replay.find(t=>t.id===cur.currentCostSourceTxId&&TYPES[t.type]?.cat==='purchase');p.currentCostPrice=source?n(source.unitPrice):currentCost(cur);p.currentCostSource=cur.currentCostSource;p.currentCostSourceTxId=cur.currentCostSourceTxId;p.priceMode=cur.priceMode;p.markupMode=cur.markupMode;p.markupPercent=cur.markupPercent;p.price=source&&p.priceMode==='markup'?priceFromMarkup(p.currentCostPrice,effectiveProductMarkup(p)):cur.price;p.packEnabled=cur.packEnabled;p.unitsPerPack=cur.unitsPerPack;reconcilePhysicalPackState(p);}setStock(final);tx=replay;return true}finally{auditMuted--;}}
function availableForTx(t){if(!t.productId||!n(t.qty))return true;const cat=TYPES[t.type]?.cat;if(!['sale','adjustminus','damaged'].includes(cat))return true;const s=getStock().find(x=>x.id===t.productId);return !!s&&n(s.qty)>=n(t.qty)}

