const MONS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const r2=x=>Math.round(n(x)*100)/100;
function nowIso(){return new Date().toISOString()}
function fmtStamp(ts){if(!ts)return'';const d=new Date(ts);if(isNaN(d))return'';let h=d.getHours();const ap=h>=12?'PM':'AM';h=h%12||12;return d.getDate()+' '+MONS[d.getMonth()]+' '+d.getFullYear()+' · '+h+':'+String(d.getMinutes()).padStart(2,'0')+' '+ap}
function isPosCat(c){return POS_CATS.includes(c)}
function txLabel(t){const c=TYPES[t.type]?.cat;if(c==='cashxfer')return'Cash moved · '+(t.sourcePool==='today_sales'?'Today’s sales → POS':(t.from==='retail'?'Retail → POS':'POS → Retail'));if(c==='posadj')return'POS cash '+(t.direction==='out'?'taken out':'added');return TYPES[t.type]?.label||t.type}
function posComponents(t){const p=t.pos||{};return{cashIn:n(p.cashIn),cashOut:n(p.cashOut),elecIn:n(p.elecIn),elecOut:n(p.elecOut),fee:n(p.fee),feeVia:p.feeVia==='cash'?'cash':'elec'}}
function posBuild(type,A,B,fee,feeVia){A=r2(Math.max(0,n(A)));B=r2(Math.max(0,n(B)));fee=r2(Math.max(0,n(fee)));const c={cashIn:0,cashOut:0,elecIn:0,elecOut:0,fee,feeVia:feeVia==='cash'?'cash':'elec',principal:A};
 if(type==='pos_withdrawal'){c.cashOut=A;c.elecIn=A}else if(type==='pos_transfer'||type==='pos_deposit'){c.cashIn=A;c.elecOut=A}else if(type==='pos_collection'){c.elecIn=A}else if(type==='pos_collect_transfer'){c.elecIn=A;c.elecOut=B}else if(type==='pos_collect_withdraw'){c.elecIn=A;c.cashOut=B}
 if(fee>0){if(c.feeVia==='cash')c.cashIn=r2(c.cashIn+fee);else c.elecIn=r2(c.elecIn+fee)}return c}
/* movements of one parent transaction, derived from its components (never stored separately, so they can't go stale) */
function posMovements(t){const c=posComponents(t),o=[];const add=(k,d,a,l)=>{if(a>.004)o.push({id:t.id+'#'+k+'-'+d,parentId:t.id,kind:k,dir:d,amount:a,label:l})};add('cash','in',c.cashIn,'Cash received');add('cash','out',c.cashOut,'Cash paid out');add('electronic','in',c.elecIn,'Card/transfer received');add('electronic','out',c.elecOut,'Transfer sent');return o}
function posCashDelta(t){const c=TYPES[t.type]?.cat;if(c==='pos'){const x=posComponents(t);return x.cashIn-x.cashOut}if(c==='cashxfer'){const a=n(t.amount);return t.to==='pos'?a:(t.from==='pos'?-a:0)}if(c==='posadj')return t.direction==='out'?-n(t.amount):n(t.amount);return 0}
function posNeed(t){const c=TYPES[t.type]?.cat;if(c==='pos')return posComponents(t).cashOut;const d=posCashDelta(t);return d<0?-d:0}
function posOpeningNow(){return n($('posOpeningCash').value)}
function posElectronicOpeningNow(){return n($('posOpeningElectronic')?.value)}
function posRunning(list,open){let b=n(open);return list.map(t=>{b+=posCashDelta(t);return r2(b)})}
function posElectronicDelta(t){if(TYPES[t.type]?.cat!=='pos')return 0;const c=posComponents(t);return c.elecIn-c.elecOut}
function posElectronicViolation(list,open){let b=n(open);for(let i=0;i<list.length;i++){const t=list[i];if(TYPES[t.type]?.cat!=='pos')continue;const c=posComponents(t),available=b+c.elecIn;if(c.elecOut>available+.004)return{index:i,tx:t,available:Math.max(0,r2(available)),required:r2(c.elecOut)};b=available-c.elecOut}return null}
/* first step where physical cash would have to leave a POS till that doesn't hold enough */
function posCashViolation(list,open){let b=n(open);for(let i=0;i<list.length;i++){const t=list[i],cat=TYPES[t.type]?.cat;if(cat==='pos'){const c=posComponents(t),available=b+c.cashIn;if(c.cashOut>available+.004)return{index:i,tx:t,available:Math.max(0,r2(available)),required:r2(c.cashOut)};b=available-c.cashOut;continue}const need=posNeed(t);if(need>b+.004)return{index:i,tx:t,available:Math.max(0,r2(b)),required:r2(need)};b+=posCashDelta(t)}return null}
function posShortText(v){return txLabel(v.tx)+(v.tx.ts?' ('+fmtStamp(v.tx.ts)+')':'')+' — available '+fmt(v.available)+', required '+fmt(v.required)}
function posUsed(r){const P=r.pos;return P.count>0||P.elecIn>0||P.elecOut>0||P.opening>0||P.electronicOpening>0||P.xferIn>0||P.xferOut>0||P.adjIn>0||P.adjOut>0}
function posLine(t){return t.posN||t.posIncome?'POS — '+t.posN+' transaction'+(t.posN===1?'':'s')+' · service income '+fmt(t.posIncome)+' · cash paid out '+fmt(t.posOut):''}

