function refreshPosUI(typeChanged){const ty=$('posType').value,f=POS_FORM[ty]||POS_FORM.pos_withdrawal;$('posLblA').textContent=f.a;if($('posTypeHelp'))$('posTypeHelp').textContent=f.help||'';$('posBWrap').classList.toggle('hidden',!f.b);if(f.b)$('posLblB').textContent=f.b;if(typeChanged===true){posFeeVia=f.via;syncFeeViaSeg()}$('posFeeVia').classList.toggle('hidden',!(n($('posFee').value)>0));const d=posDraft(),el=$('posEffect');if(!(d.A>0)){el.textContent='';el.classList.remove('bad');return}const c=d.comp,net=r2(c.cashIn-c.cashOut),base=calc(posBaseList()).pos,avail=base.expectedCash,eAvail=base.expectedElectronic,parts=[];if(c.cashIn||c.cashOut)parts.push('Cash '+(net>=0?'+':'−')+fmt(Math.abs(net)));if(c.elecIn)parts.push('Electronic +'+fmt(c.elecIn));if(c.elecOut)parts.push('Electronic −'+fmt(c.elecOut));if(c.fee)parts.push('Charge '+fmt(c.fee)+' is income');const cashBad=c.cashOut>avail+.004,elecBad=c.elecOut>eAvail+c.elecIn+.004;parts.push(cashBad?'Insufficient POS cash — available '+fmt(avail):'POS cash after '+fmt(avail+net));parts.push(elecBad?'Insufficient POS electronic balance — available '+fmt(eAvail+c.elecIn):'Electronic balance after '+fmt(eAvail+c.elecIn-c.elecOut));el.textContent=parts.join(' · ');el.classList.toggle('bad',cashBad||elecBad)}
function refreshPosBal(r){const el=$('posBal');if(el)el.innerHTML='POS cash <b>'+esc(fmt(r.pos.expectedCash))+'</b> · Electronic <b>'+esc(fmt(r.pos.expectedElectronic))+'</b> · Retail cash '+esc(fmt(r.expectedCash))}
