function resetPosForm(){posEditIndex=-1;['posA','posB','posFee','posRef','posParty'].forEach(id=>$(id).value='');$('posChannel').value='';$('posAddBtn').textContent='Add';$('posCancelEditBtn').classList.add('hidden');$('posWarn').textContent='';hideShort();const legacy=$('posType').querySelector('option[data-legacy="1"]');if(legacy){$('posType').value='pos_withdrawal';legacy.remove()}posFeeVia=(POS_FORM[$('posType').value]||POS_FORM.pos_withdrawal).via;syncFeeViaSeg();refreshPosUI(false)}
