function posValidate(d){const values=[d.A,d.B,d.fee,...Object.values(d.comp).filter(v=>typeof v==='number')];if(values.some(v=>!Number.isFinite(v)||v<0||v>1e12||!Number.isSafeInteger(Math.round(v*100))))return'Enter valid nonnegative amounts, up to 1 trillion, including fees.';if(!(d.A>0))return'Enter an amount greater than zero.';const f=POS_FORM[d.ty];if(!f)return'Choose a supported POS transaction.';if(f.b&&!(d.B>0))return'Enter '+f.b.toLowerCase()+'.';if((d.ty==='pos_collect_transfer'||d.ty==='pos_collect_withdraw')&&d.B>d.A+.004)return f.b+' cannot exceed the amount received.';return''}
