function xferRefresh(){const dir=$('xferDir').value,adj=dir==='padd'||dir==='prem',r=calc(xferBase());$('xferBal').textContent='Retail cash '+fmt(r.expectedCash)+' · Today’s sales cash '+fmt(todaySalesCashAvailable(xferBase()))+' · POS cash '+fmt(r.pos.expectedCash);$('xferNoteLbl').textContent=adj?'Reason (required)':'Note (optional)';$('xferErr').classList.add('hidden')}
function openXfer(pre){if(currentDesk!=='sales')switchDesk('sales');xferEditIndex=-1;$('xferDir').value=pre?.dir||'r2p';$('xferAmt').value=pre?.amount||'';$('xferNote').value=pre?.note||'';$('xferOk').textContent='Move cash';xferRefresh();$('xferOverlay').classList.remove('hidden');setTimeout(()=>$('xferAmt').focus(),50)}
function todaySalesCashAvailable(list=tx){let sales=0,refunds=0,moved=0;for(const t of list){if(t.type==='sale_cash')sales+=n(t.amount);else if(t.type==='sale_split')sales+=n(t.splitCash);else if(t.type==='refund_cash')refunds+=n(t.amount);else if(t.type==='cash_transfer'&&t.sourcePool==='today_sales')moved+=n(t.amount)}return Math.max(0,sales-refunds-moved)}
function startXferEdit(i){const t=tx[i];openXfer(null);xferEditIndex=i;$('xferDir').value=t.type==='cash_transfer'?(t.sourcePool==='today_sales'?'ts2p':(t.from==='retail'?'r2p':'p2r')):(t.direction==='out'?'prem':'padd');$('xferAmt').value=t.amount;$('xferNote').value=t.note||'';$('xferOk').textContent='Save';xferRefresh()}
function closeXfer(){$('xferOverlay').classList.add('hidden');xferEditIndex=-1}
$('xferDir').addEventListener('change',xferRefresh);$('xferCancel').addEventListener('click',closeXfer);$('xferOverlay').addEventListener('click',e=>{if(e.target===$('xferOverlay'))closeXfer()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('xferOverlay').classList.contains('hidden'))closeXfer()});
$('xferOk').addEventListener('click',async()=>{if(historical||inventoryBusy||backupWorkApplying)return showToast('A business save is finishing. Your cash move form was kept; try again shortly.');const dir=$('xferDir').value,amt=r2($('xferAmt').value),note=$('xferNote').value.trim(),adj=dir==='padd'||dir==='prem',err=m=>{$('xferErr').textContent=m;$('xferErr').classList.remove('hidden')};if(!Number.isFinite(amt)||!(amt>0)||amt>1e12)return err('Enter a valid amount greater than zero, up to 1 trillion.');if(adj&&!note)return err('Add a short reason for this POS cash adjustment.');const old=xferEditIndex>=0?tx[xferEditIndex]:null;let o;if(adj)o={id:old?old.id:uid('t'),type:'pos_cash_adjust',domain:'pos',refKind:'pos',direction:dir==='padd'?'in':'out',amount:amt,unitPrice:amt,qty:0,note,ref:'',party:'',productId:null,productName:null,division:null,costSnapshot:0,ts:old&&old.ts?old.ts:nowIso()};else o={id:old?old.id:uid('t'),type:'cash_transfer',domain:'internal',refKind:'internal',from:(dir==='r2p'||dir==='ts2p')?'retail':'pos',to:(dir==='r2p'||dir==='ts2p')?'pos':'retail',sourcePool:dir==='ts2p'?'today_sales':null,amount:amt,unitPrice:amt,qty:0,note,ref:old?.ref||('MC-'+Date.now().toString(36).toUpperCase()),party:'',productId:null,productName:null,division:null,costSnapshot:0,ts:old&&old.ts?old.ts:nowIso()};if(old)o.editedAt=nowIso();const base=xferBase();if(o.type==='cash_transfer'&&o.from==='retail'){const av=calc(base).expectedCash;if(amt>av+.004)return err('Insufficient retail cash. Available: '+fmt(av)+' · Required: '+fmt(amt));if(o.sourcePool==='today_sales'){const saleAv=todaySalesCashAvailable(base);if(amt>saleAv+.004)return err('Insufficient cash from today’s sales. Available: '+fmt(saleAv)+' · Required: '+fmt(amt))}}const next=old?tx.map((t,i)=>i===xferEditIndex?o:t):[...tx,o],v=posCashViolation(next,posOpeningNow());if(v)return err('Insufficient POS cash. Available: '+fmt(v.available)+' · Required: '+fmt(v.required));const saved=await inventoryCommit(()=>{ensureOpeningStock();tx=next;return true},'Sales Desk','Cash move');if(saved!==true)return;closeXfer();render();toast(old?'Cash move updated':(o.type==='cash_transfer'?'Cash moved: '+fmt(amt)+' '+(o.from==='retail'?'Retail → POS':'POS → Retail'):'POS cash adjusted'))});

