function txMatchesFilter(t){const cat=TYPES[t.type]?.cat,kind=$('txKindFilter')?.value||'all',isPos=cat==='pos'||cat==='posadj',isCash=cat==='cashxfer';if(kind==='retail'&&(isPos||isCash))return false;if(kind==='pos'&&!isPos)return false;if(kind==='cash'&&!(isCash||cat==='posadj'))return false;const f=$('txDivFilter').value||'all';if(f!=='all'){if(!PRODCATS.includes(cat))return false;if((txDiv(t)||'unassigned')!==f)return false}const q=($('txSearch')?.value||'').trim().toLowerCase();if(q){const hay=[txLabel(t),t.note,t.ref,t.party,t.channel,t.productName,String(t.amount),fmtStamp(t.ts),t.id].join(' ').toLowerCase();if(!hay.includes(q))return false}return true}
