$('ledger').addEventListener('click',e=>{const more=e.target.closest('[data-ledger-more]');if(more){PERF.ledgerLimit+=PERF.ledgerPage;return renderLedger()}const b=e.target.closest('[data-tog]');if(!b)return;const id=b.dataset.tog;if(openDetails.has(id))openDetails.delete(id);else openDetails.add(id);renderLedger()});
