function stableBackupText(value){const clean=v=>{if(Array.isArray(v))return v.map(clean);if(v&&typeof v==='object'){const out={};Object.keys(v).sort().forEach(k=>out[k]=clean(v[k]));return out}return v};return JSON.stringify(clean(value))}
function checkWorkingMarketContext(data){const current=workingMarketContext(),context=data.linkedMarketContext;const linked=list=>(list||[]).filter(t=>t.marketPurchaseId||t.supplierPurchaseId||t.supplierPaymentId).map(t=>({id:t.id,type:t.type,amount:t.amount,qty:t.qty,productId:t.productId,marketPurchaseId:t.marketPurchaseId,supplierPurchaseId:t.supplierPurchaseId,supplierPaymentId:t.supplierPaymentId})).sort((a,b)=>String(a.id).localeCompare(String(b.id)));if(context){if(context.version!==1||!Array.isArray(context.history)||!Array.isArray(context.marketPurchases))throw Error('This Working Stock backup has damaged Market purchase context. Use a Full Backup.');if(stableBackupText(context)!==stableBackupText(current)||stableBackupText(linked(data.currentDay?.tx))!==stableBackupText(linked(tx)))throw Error('Market purchases or supplier payments have changed since this Working Stock backup. Restore a matching Full Backup to keep stock, transactions and supplier balances together.');const stockIds=new Set(data.stock.map(p=>String(p.id)));if(linked(data.currentDay?.tx).some(t=>t.productId&&!stockIds.has(String(t.productId))))throw Error('This Working Stock backup is missing stock linked to a Market purchase. Use a matching Full Backup.')}else if(current.history.length||current.marketPurchases.length||(data.currentDay?.tx||[]).some(t=>t.marketPurchaseId||t.supplierPurchaseId||t.supplierPaymentId)||tx.some(t=>t.marketPurchaseId||t.supplierPurchaseId||t.supplierPaymentId))throw Error('This older Working Stock backup has no linked Market purchase context. Use a matching Full Backup when Market purchases or supplier balances exist.')}
