const RM=window.RoseachyMatch;
/* Duplicate detection is READ-ONLY: it only reads inventory and never changes stock, names, prices, packs or divisions. */
function duplicateScore(a,b){const r=RM.analyze(a,b);return RM.actionable(r.kind)?r.score:0}
function duplicateCandidates(name,excludeId=null){return getStock().filter(x=>x.id!==excludeId).map(x=>{const r=RM.analyze(name,x.name);return{product:x,score:r.score,kind:r.kind,spelling:r.spelling,notes:r.notes,conflicts:r.conflicts}}).filter(x=>RM.actionable(x.kind)).sort((a,b)=>b.score-a.score).slice(0,4)}
