 if(hasContext){tx=normalizeTxIds(clone(data.currentDay.tx||[])).list;openingStock=clone(data.currentDay.openingStock||{});const f=data.currentDay.fields||{};stateFields.forEach(id=>{const el=$(id);if(el&&f[id]!==undefined)el.value=f[id]})}
