function renderWeekly(){const from=$('weekFrom').value,to=$('weekTo').value,rows=weeklyRows(from,to);let t={netSales:0,cashSales:0,nonCashSales:0,profit:0,expenses:0,refunds:0,units:0,posN:0,posIncome:0,posOut:0};rows.forEach(rec=>{const c=recordCalc(rec);t.posN+=c.pos.count;t.posIncome+=c.pos.income;t.posOut+=c.pos.cashOut;t.netSales+=c.netSales;t.cashSales+=c.cashSales;t.nonCashSales+=c.nonCashSales;t.profit+=c.grossProfit;t.expenses+=c.expenses;t.refunds+=c.refunds;t.units+=c.unitsSold;DIVK.forEach(k=>t[k]=(t[k]||0)+c.byDiv[k].sales-c.byDiv[k].refunds)});$('wDivLine').textContent=divNetLine(t);$('wPosLine').textContent=posLine(t);$('wSales').textContent=fmt(t.cashSales+t.nonCashSales);$('wCashSales').textContent=fmt(t.cashSales);$('wNonCashSales').textContent=fmt(t.nonCashSales);$('wProfit').textContent=fmt(t.profit);$('wExpenses').textContent=fmt(t.expenses);$('wRefunds').textContent=fmt(t.refunds);$('wUnits').textContent=t.units;$('wMargin').textContent=(t.netSales>0?(t.profit/t.netSales*100):0).toFixed(1)+'%';const body=$('weeklyBreakdown');body.innerHTML=rows.length?'':'<tr><td colspan="5" class="empty">No saved days in this range</td></tr>';rows.slice(-120).forEach(rec=>{const c=recordCalc(rec),tr=document.createElement('tr');tr.innerHTML='<td>'+esc(rec.date||'')+'</td><td>Roseachy</td><td class="num">'+fmt(c.netSales)+'</td><td class="num">'+fmt(c.grossProfit)+'</td><td class="num">'+fmt(c.expenses)+'</td>';body.appendChild(tr)});if(rows.length>120){const tr=document.createElement('tr');tr.innerHTML='<td colspan="5" class="empty">Showing the latest 120 days in this table. Totals above include the full selected range.</td>';body.insertBefore(tr,body.firstChild)}}
