  restoring=true;backupWorkApplying=true;const committed=await inventoryCommit(()=>{applyBackupData(d);return true},'Backup restore');backupWorkApplying=false;if(committed!==true)throw Error('Backup restore was not committed.');await RS.whenSaved();const verified=await RS.verify();if(!verified.ok)throw Error('Restored records failed database verification: '+verified.bad.join(', '));
