async function monitorStorageSize(){const el=$('storagePerfWarn');if(!el||!navigator.storage?.estimate)return;try{const e=await navigator.storage.estimate(),usage=n(e.usage),quota=n(e.quota),ratio=quota>0?usage/quota:0;const large=usage>150*1024*1024||ratio>.65;el.classList.toggle('hidden',!large);if(large)el.textContent='Storage is becoming large ('+(usage/1024/1024).toFixed(1)+' MB). Export a Full Backup to another location and check phone storage. Roseachy will not delete business history automatically.'}catch{el.classList.add('hidden')}}

/* ---- bounded native-like internal Back navigation ---- */
const ROSEACHY_NAV_OVERLAYS=['syncOverlay','dupOverlay','xferOverlay','marketStockOverlay','marketReqOverlay','marketReviewOverlay','marketHistoryOverlay','marketSummaryOverlay','marketCalcOverlay','supplierEditOverlay','supplierDetailOverlay','supplierPaymentOverlay','marketListPickerOverlay','marketListActionOverlay','marketRecycleOverlay','marketPurchaseDetailOverlay'];
function roseachyActiveTab(){return ['Tx','Stock','Report','Notes','Analytics'].find(t=>!$('tab'+t)?.classList.contains('hidden'))||'Tx'}
function roseachyNavSnapshot(){return{desk:currentDesk||'sales',tab:roseachyActiveTab(),entryMode:entryMode||'retail',marketView:marketView||'active',marketCalcMode:marketCalcMode||'digital',scrollY:Math.max(0,window.scrollY||0),openBodies:[...document.querySelectorAll('.collapseBody.open')].map(x=>x.id),inventoryCollapsed:!!getUIState().stockInventoryCollapsed,stockMultiMode:!!stockMultiMode,stockSelectedIds:[...stockSelectedIds],openDetails:[...openDetails],overlays:[]}}
function roseachyNavSig(st){if(!st)return'';const c={...st,scrollY:0,overlays:[]};return JSON.stringify(c)}
(function(){
 let ready=false,restoring=false,handlingBack=false,sentinelActive=false,current=null,path=[],home=null;
 const MAX_DEPTH=8;
 function capture(){return roseachyNavSnapshot()}
 function clean(st){return {...st,overlays:[]}}
 function makeHome(seed){return clean({...seed,desk:'sales',tab:'Tx',entryMode:'retail',scrollY:0,openBodies:[...(seed?.openBodies||[])],stockMultiMode:false,stockSelectedIds:[],openDetails:[],overlays:[]})}
 function isHomeState(st){return !!(st&&st.desk==='sales'&&st.tab==='Tx'&&st.entryMode==='retail'&&!st.stockMultiMode&&!(st.openDetails||[]).length&&!(st.overlays||[]).length)}
 function sig(st){return roseachyNavSig(clean(st))}
 function same(a,b){return sig(a)===sig(b)}
 function browserState(){return{roseachySentinel:true,depth:path.length,current:sig(current),ts:Date.now()}}
 function ensureHomeAnchor(){
   if(!home||!current||isHomeState(current))return;
   if(!path.length)path=[clean(home)];
   else if(!same(path[0],home))path=[clean(home),...path.filter(x=>!same(x,home))];
 }
 function ensureSentinel(){
   if(sentinelActive){history.replaceState(browserState(),'',location.href);return}
   history.pushState(browserState(),'',location.href);sentinelActive=true
 }
 function replace(){if(!ready||restoring||handlingBack)return;const next=clean(capture());if(home&&isHomeState(next)){path=[];current=next}else{let ancestor=-1;for(let i=path.length-1;i>=0;i--){if(same(next,path[i])){ancestor=i;break}}if(ancestor>=0){path=path.slice(0,ancestor);current=next}else current=next}if(sentinelActive)history.replaceState(browserState(),'',location.href)}
 function commit(){
   if(!ready||restoring||handlingBack)return;
   ensureHomeAnchor();
   const next=clean(capture());
   if(!current){current=next;ensureSentinel();return}
   if(same(next,current)){current=next;if(sentinelActive)history.replaceState(browserState(),'',location.href);return}
   /* If forward navigation returns to an ancestor/parent, consume the child path instead of creating a circle. */
   let ancestor=-1;
   for(let i=path.length-1;i>=0;i--){if(same(next,path[i])){ancestor=i;break}}
   if(ancestor>=0){path=path.slice(0,ancestor);current=next;if(sentinelActive)history.replaceState(browserState(),'',location.href);else ensureSentinel();return}
   /* Returning directly to Home consumes the entire internal path. */
   if(home&&isHomeState(next)){path=[];current=next;if(sentinelActive)history.replaceState(browserState(),'',location.href);return}
   path.push(clean(current));
   if(path.length>MAX_DEPTH)path=path.slice(path.length-MAX_DEPTH);
   current=next;
   if(sentinelActive)history.replaceState(browserState(),'',location.href);else ensureSentinel()
 }
 function restore(st){
   if(!st)return;
   restoring=true;
   try{
     switchDesk(st.desk||'sales',false);
     if((st.desk||'sales')==='sales'){setTab(st.tab||'Tx',false);setEntryMode(st.entryMode||'retail',false)}
     if((st.desk||'sales')==='market'){setMarketView(st.marketView||'active',false);setMarketCalcMode(st.marketCalcMode||'digital',false)}
     document.querySelectorAll('.collapseBody').forEach(b=>{const on=(st.openBodies||[]).includes(b.id);b.classList.toggle('open',on);document.querySelector('.collapseHead[data-target="'+CSS.escape(b.id)+'"]')?.setAttribute('aria-expanded',on?'true':'false')});
     syncStockInventoryCollapse(!!st.inventoryCollapsed);
     stockMultiMode=!!st.stockMultiMode;stockSelectedIds=new Set(st.stockSelectedIds||[]);if(stockMultiMode)renderStock();else exitStockMultiMode(false);
     openDetails=new Set(st.openDetails||[]);if((st.desk||'sales')==='sales'&&(st.tab||'Tx')==='Tx')renderLedger();
     ROSEACHY_NAV_OVERLAYS.forEach(id=>$(id)?.classList.add('hidden'));
     $('deskMenu')?.classList.add('hidden');$('marketUtilityMenu')?.classList.add('hidden');closeProductSuggestions?.();
     requestAnimationFrame(()=>window.scrollTo({top:Math.max(0,Number(st.scrollY)||0),behavior:'auto'}));
     current=clean(st)
   } finally {requestAnimationFrame(()=>{restoring=false})}
 }
 function closeTemporary(){
   const suggestions=$('productSuggestions');
   if(suggestions&&!suggestions.classList.contains('hidden')){closeProductSuggestions?.();return true}
   const marketMenu=$('marketUtilityMenu');
   if(marketMenu&&!marketMenu.classList.contains('hidden')){closeMarketUtilityMenu?.();return true}
   const financeMenu=$('finMenu');if(financeMenu&&!financeMenu.classList.contains('hidden')&&currentDesk==='financial'){financeMenu.classList.add('hidden');return true}
   const deskMenu=$('deskMenu');
   if(deskMenu&&!deskMenu.classList.contains('hidden')){deskMenu.classList.add('hidden');return true}
   for(let i=ROSEACHY_NAV_OVERLAYS.length-1;i>=0;i--){const el=$(ROSEACHY_NAV_OVERLAYS[i]);if(el&&!el.classList.contains('hidden')){el.classList.add('hidden');return true}}
   if(stockMultiMode){exitStockMultiMode(false);renderStock();replace();return true}
   return false
 }
 function backInternal(){
   if(currentDesk==='financial'&&(finBusy||roseachyBackupBusy)){showToast('A Financial Desk action is finishing. Try Back again shortly.');return true}
   if(closeTemporary())return true;
   ensureHomeAnchor();
   if(path.length){
     const prev=path.pop();
     restore(prev);
     /* Home is the terminal internal destination. Once restored, discard any stale child history. */
     if(home&&isHomeState(prev))path=[];
     return true
   }
   if(home&&current&&!isHomeState(current)){restore(home);path=[];return true}
   return false
 }
 function initNav(){
   if(ready)return;
   ready=true;
   current=clean(capture());home=makeHome(current);
   if(!isHomeState(current))path=[home];
   /* Keep browser history shallow. At clean Home there is no sentinel, so one physical Back can leave the PWA. */
   history.replaceState({roseachyRoot:true},'',location.href);
   if(!isHomeState(current))ensureSentinel();
   window.addEventListener('popstate',()=>{
     if(restoring||handlingBack)return;
     handlingBack=true;sentinelActive=false;
     const handled=backInternal();
     requestAnimationFrame(()=>{
       if(handled){handlingBack=false;if(!(isHomeState(current)&&path.length===0))ensureSentinel();return}
       handlingBack=false;
       /* Exit is permitted only from Roseachy's clean Home screen. If anything drifted, restore Home first. */
       if(home&&current&&!isHomeState(current)){restore(home);path=[];handlingBack=false;return}
       /* Do not programmatically call history.back() here. At clean Home, this physical Back press only disarms Roseachy's sentinel. The next physical Back is allowed to leave/close the PWA naturally. This avoids recursive popstate/history-back loops on Android/WebView. */
       sentinelActive=false
     })
   });
   /* When clean Home has no sentinel, opening a dismissible temporary layer arms one so Back closes the layer instead of leaving the app. */
   const transientIds=[...ROSEACHY_NAV_OVERLAYS,'deskMenu','marketUtilityMenu','productSuggestions','finMenu'];
   const transientObserver=new MutationObserver(()=>{if(restoring||handlingBack)return;const any=transientIds.some(id=>{const el=$(id);return el&&!el.classList.contains('hidden')});if(any&&!sentinelActive)ensureSentinel()});
   transientIds.forEach(id=>{const el=$(id);if(el)transientObserver.observe(el,{attributes:true,attributeFilter:['class']})});
   document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&!restoring&&!handlingBack)replace()})
 }
 window.RoseachyNav={commit,replace,restore,init:initNav,isRestoring:()=>restoring||handlingBack,debug:()=>({depth:path.length,current:clean(current),home:clean(home),sentinelActive})};
})();

/* Financial Desk v1: inside Roseachy's main closure, reuses the authoritative transaction system. */
const FIN_META='roseachy_finance_vault_v1', FIN_PUBLIC='roseachy_finance_review_v1';
let finEntered=false,finKey=null,finPrivate=null,finBusy=false,finView='overview',finPage=0,finUnmasked=true;
const fin$=id=>$(id), finK=v=>Math.round(Number(v)*100),finN=k=>(Number(k)||0)/100;
const finMoney=k=>fmt(finN(k));
function finValidPin(v){return /^\d{4}$/.test(String(v||''))}
const FIN_PIN_NEW=['finSetupPassword','finSetupPassword2','finRecoveryNew','finRecoveryNew2','finNewPass','finNewPass2'];
const FIN_PIN_OLD=['finUnlockPass','finCurrentPassword','finEditPassword'];
const FIN_PIN_IDS=[...FIN_PIN_NEW,...FIN_PIN_OLD];
function finIsPinAccount(){return finStored()?.pinLength===4}
function finInitPinFields(){
 for(const id of FIN_PIN_IDS){
  const source=fin$(id);if(!source||source.dataset.pinPrepared)return;
  source.dataset.pinPrepared='1';
  const group=document.createElement('div');group.className='finPinGroup';group.dataset.pinFor=id;group.setAttribute('role','group');group.setAttribute('aria-label',id==='finUnlockPass'?'Four-digit financial PIN':'Four-digit PIN');
  const digits=[];
  for(let i=0;i<4;i++){
   const inp=document.createElement('input');inp.className='finPinDigit';inp.type='password';inp.inputMode='numeric';inp.pattern='[0-9]*';inp.maxLength=1;inp.autocomplete='off';inp.setAttribute('aria-label','PIN digit '+(i+1)+' of 4');inp.dataset.finPin=id;inp.dataset.digitIndex=String(i);digits.push(inp);group.appendChild(inp);
  }
  source.parentNode.insertBefore(group,source);
  const sync=()=>{source.value=digits.map(x=>x.value).join('')};
  const distribute=(start,text)=>{
   const only=String(text||'').replace(/\D/g,'');if(!only)return;
   for(let i=0;i<only.length&&start+i<4;i++)digits[start+i].value=only[i];sync();
   const next=Math.min(4,start+only.length);if(next<4)digits[next].focus();else digits[3].blur();
  };
  digits.forEach((inp,i)=>{
   inp.addEventListener('focus',()=>{if(inp.value)inp.select()});
   inp.addEventListener('input',()=>{const text=inp.value;inp.value='';distribute(i,text);if(!/\d/.test(text))sync()});
   inp.addEventListener('keydown',e=>{
    if(e.key==='Backspace'){
     e.preventDefault();if(inp.value){inp.value='';sync()}else if(i>0){digits[i-1].value='';digits[i-1].focus();sync()}
    }else if(e.key==='Delete'){e.preventDefault();inp.value='';sync()}
    else if(e.key==='ArrowLeft'&&i){e.preventDefault();digits[i-1].focus()}
    else if(e.key==='ArrowRight'&&i<3){e.preventDefault();digits[i+1].focus()}
    else if(e.key==='Enter'){e.preventDefault();const button=id==='finUnlockPass'?'finUnlockGo':id.startsWith('finSetup')?'finSetupGo':id.startsWith('finRecovery')?'finRecoveryGo':id.startsWith('finNew')?'finChangePass':null;if(button)fin$(button)?.click()}
   });
   inp.addEventListener('paste',e=>{e.preventDefault();distribute(i,e.clipboardData?.getData('text')||'')});
  });
 }
 finPinRefresh();
}
function finPinRefresh(){
 for(const id of FIN_PIN_IDS){
  const src=fin$(id),group=document.querySelector('[data-pin-for="'+id+'"]');if(!src||!group)continue;
  const pin=FIN_PIN_NEW.includes(id)||finIsPinAccount();
  group.classList.toggle('hidden',!pin);src.classList.toggle('finPinOriginalHidden',pin);
  if(pin)src.setAttribute('aria-hidden','true');else src.removeAttribute('aria-hidden');
 }
}
function finPinFocus(id){finPinRefresh();const group=document.querySelector('[data-pin-for="'+id+'"]');if(group&&!group.classList.contains('hidden'))group.querySelector('.finPinDigit')?.focus();else fin$(id)?.focus()}
function finPinClear(ids=FIN_PIN_IDS){for(const id of ids){const src=fin$(id),group=document.querySelector('[data-pin-for="'+id+'"]');if(src)src.value='';group?.querySelectorAll('.finPinDigit').forEach(x=>x.value='')}}
function finStored(){try{return JSON.parse(safeGet(FIN_META)||'null')}catch{return null}}
function finPublic(){try{const a=JSON.parse(safeGet(FIN_PUBLIC)||'{}');return {confirmed:a.confirmed||{},reviewed:a.reviewed||{}}}catch{return {confirmed:{},reviewed:{}}}}
function finPublicWrite(x){storeSet(FIN_PUBLIC,JSON.stringify(x))}
function finCurrentDate(){return fin$('date').value||today()}
function finReviewSignature(date){if(!finPrivate)return null;const rows=finSourceRows().filter(r=>r.date<=date).map(r=>[r.id,r.date,r.k]).sort((a,b)=>String(a[0]).localeCompare(String(b[0])));const payload=JSON.stringify([finPrivate.anchor.amountK,finPrivate.anchor.asOf,rows]);let h1=2166136261,h2=5381;for(let i=0;i<payload.length;i++){const c=payload.charCodeAt(i);h1=Math.imul(h1^c,16777619);h2=Math.imul(h2,33)^c;}return rows.length+':'+(h1>>>0).toString(16)+':'+(h2>>>0).toString(16);}
function finReviewValid(date,pub){const record=(pub||finPublic()).reviewed[date];if(!record)return false;if(!finPrivate)return true;return !!record.signature&&record.signature===finReviewSignature(date);}
function finIsPending(){const d=finCurrentDate(),p=finPublic();return !!p.confirmed[d]&&!finReviewValid(d,p)}
function finReminder(){const pub=finPublic(),date=finCurrentDate(),pending=!!pub.confirmed[date]&&!finReviewValid(date,pub),menu=fin$('deskMenu'),open=!menu.classList.contains('hidden');fin$('deskMenuBtn').classList.toggle('finPulse',pending&&!open);fin$('financeMenuEntry').classList.toggle('finPulseItem',pending&&open);fin$('financeMenuEntry').querySelector('.finDot').classList.toggle('hidden',!pending);const note=fin$('finDayConfirmStatus');if(note)note.textContent=finReviewValid(date,pub)?'Day setup confirmed · bank review completed':pub.confirmed[date]?'Day setup confirmed · bank review pending':'Bank review reminder starts after confirmation';}
function finCollapseDaySetup(){const body=fin$('daySetupBody'),head=document.querySelector('.collapseHead[data-target="daySetupBody"]');if(body){body.classList.remove('open');head?.setAttribute('aria-expanded','false');window.RoseachyNav?.replace?.()}}
function finClearReviewPulse(){fin$('deskMenuBtn').classList.remove('finPulse');fin$('financeMenuEntry').classList.remove('finPulseItem');fin$('financeMenuEntry').querySelector('.finDot').classList.add('hidden')}
function finBytes(v){return Uint8Array.from(atob(v),x=>x.charCodeAt(0))}
function finB64(v){const a=new Uint8Array(v);let s='';for(let i=0;i<a.length;i++)s+=String.fromCharCode(a[i]);return btoa(s)}
function finRandom(n){const a=new Uint8Array(n);crypto.getRandomValues(a);return a}
function finKeyText(){const a=finRandom(32),hex=Array.from(a,x=>x.toString(16).padStart(2,'0')).join('').toUpperCase();return hex.match(/.{1,4}/g).join('-')}
function finNormalizeKey(v){return String(v||'').replace(/[^a-f0-9]/gi,'').toUpperCase()}
async function finDerive(secret,salt){const original=await crypto.subtle.importKey('raw',new TextEncoder().encode(secret),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt:finBytes(salt),iterations:260000,hash:'SHA-256'},original,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function finSeal(key,plain){const iv=finRandom(12),ct=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,plain);return {iv:finB64(iv),data:finB64(ct)}}
async function finOpen(key,box){return crypto.subtle.decrypt({name:'AES-GCM',iv:finBytes(box.iv)},key,finBytes(box.data))}
async function finWrap(raw,secret){const salt=finB64(finRandom(16)),key=await finDerive(secret,salt);return {salt,box:await finSeal(key,raw)}}
async function finUnwrap(box,secret){const key=await finDerive(secret,box.salt);return finOpen(key,box.box)}
function finVaultBase(anchorK,asOf){return {version:1,anchor:{amountK:anchorK,asOf,createdAt:new Date().toISOString()},events:[],reviews:[]}}
async function finCommitMeta(meta,review=null){while(inventoryBusy||auditCleanupBusy)await new Promise(r=>setTimeout(r,25));try{await RS.atomic(()=>{storeSet(FIN_META,JSON.stringify(meta));if(review)finPublicWrite(review)})}finally{PERF.parsed.delete(FIN_META);PERF.parsed.delete(FIN_PUBLIC)}}
async function finPersist(review=null){if(!finKey||!finPrivate)throw Error('Financial Desk is locked');const meta=finStored();if(!meta)throw Error('Financial setup is missing');const previousVault=clone(meta.vault);meta.vault=await finSeal(finKey,new TextEncoder().encode(JSON.stringify(finPrivate)));await SmartSync.prepareFinancial(previousVault,meta.vault,finPrivate,finKey);await finCommitMeta(meta,review)}
/* Desk switches discard the unlocked session; unfinished work stays encrypted. */
let finDeskExitSaved=Promise.resolve(),finDeskEpoch=0;
function finLockForDeskExit(){
 if(finKey){
  // Capture with the current key before clearing it. Serialize the write after any
  // existing autosave so a late autosave cannot replace this final private draft.
  const capture=backupCaptureWorking();
  backupWorkGeneration++;
  const saved=Promise.all([backupWorkChain.catch(()=>{}),capture]).then(async([,state])=>{
   storeSet(BACKUP_WORK_KEY,JSON.stringify(state));await RS.whenSaved();
  });
  backupWorkChain=saved.catch(e=>showToast('Financial Desk locked, but unfinished work was not saved: '+(e.message||e))).finally(()=>{if(!finKey)backupFinanceCache=null});
  finDeskExitSaved=backupWorkChain;
 }
 finClose();backupFinanceCache=null;
}

