const AUDIT_KEY='roseachy_inventory_audit_v1';
let inventoryMessage=null,inventoryBusy=false,auditMuted=0,auditCause=null,auditPending=null,auditTracked=new Map(),auditHistoryLimit=50;
// Adjustment History holds only the last seven rolling 24-hour periods.
// This retention applies to *audit detail rows*, never to stock balances, saved-day
// ledgers, Product History, existing external backup files, or financial reports.
const AUDIT_RETENTION_MS=7*24*60*60*1000;
function auditInWindow(row,now=Date.now()){
  const ts=Date.parse(row?.timestamp);
  // Future-dated records are kept, so clock mistakes cannot destroy them.
  return Number.isFinite(ts) && ts>now-AUDIT_RETENTION_MS;
}
function auditVisibleRecords(){return auditRecords().filter(r=>auditInWindow(r));}
function expireInventoryAudit(){
  const old=auditRecords(),now=Date.now(),expired=old.filter(r=>!auditInWindow(r,now));
  if(!expired.length)return 0;
  RS.setCollection(AUDIT_KEY,old.filter(r=>auditInWindow(r,now)),expired.map(r=>r.id));
  return expired.length;
}
let auditCleanupBusy=false,auditCleanupPromise=Promise.resolve();
async function cleanAdjustmentHistory(){
  if(auditCleanupBusy||inventoryBusy)return;
  auditCleanupBusy=true;
  try{
    auditCleanupPromise=RS.atomic(()=>expireInventoryAudit());
    await auditCleanupPromise;
    if($('inventoryAuditList'))renderInventoryAudit();
  }catch(error){console.warn('Adjustment History cleanup will retry:',error);}
  finally{auditCleanupBusy=false;}
}

