 rail.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const i=order.findIndex(t=>$('tabBtn'+t)===e.target);if(i<0)return;e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?order.length-1:Math.max(0,Math.min(order.length-1,i+(e.key==='ArrowRight'?1:-1)));setTab(order[n]);$('tabBtn'+order[n]).focus({preventScroll:true})});
