 async function acceptAcknowledgement(p){return guard(async()=>{const s=copy(state());if(p.kind!=='acknowledgement'||p.businessId!==s.businessId||p.checkpointId!==s.checkpoint?.id||!s.members.includes(p.sender.deviceId))throw Error('Acknowledgement is for another business, checkpoint or unenrolled device.');const local=await known();s.peers[p.sender.deviceId]={known:copy(p.known),label:p.sender.label,enrolledAt:nowIso(),confirmedAt:nowIso(),awaitingConfirmation:!local.complete||!p.known?.complete||local.digest!==p.known?.digest};if(local.complete&&p.known?.complete&&local.digest===p.known?.digest){s.lastConfirmed={at:nowIso(),digest:local.digest,peer:p.sender.deviceId};s.status='Synchronized to Confirmed Checkpoint'}else s.status='Local Changes Pending';await write(()=>persist(s));return {matching:local.complete&&p.known?.complete&&local.digest===p.known?.digest,status:s.status}})}
 async function join(remote,{sameBusiness=false,approvedBy=''}={}){return guard(async()=>{const s=copy(state());if(!sameBusiness||!approvedBy||remote.kind!=='offer'||remote.businessId!==s.businessId||remote.checkpoint?.id!==s.checkpoint?.id)throw Error('New/recovered devices need explicit confirmation of the same existing checkpoint.');proof(remote.recovery);const cp=await openCheckpoint(s.checkpoint);if(!equal(cp.stock,remote.checkpoint.stock)||!equal(cp.records,remote.checkpoint.records)||!equal(cp.accounts,remote.checkpoint.accounts))throw Error('Recovered-device checkpoint content differs. Supervised reconciliation is required.');cp.members=[...new Set([...cp.members,remote.sender.deviceId])];cp.offers[remote.sender.deviceId]=remote.offerId;cp.proofs[remote.sender.deviceId]=remote.recovery;cp.cut[remote.sender.deviceId]=(remote.originStartSeq||1)-1;cp.enrollmentVersion=(cp.enrollmentVersion||1)+1;cp.enrollmentApprovedBy=approvedBy;s.members=cp.members;s.checkpoint=await sealCheckpoint(cp);await write(()=>persist(s));return cp})}
 async function acceptJoin(cp,{sameBusiness=false,approvedBy=''}={}){return guard(async()=>{const s=copy(state());validateCheckpoint(cp);if(!sameBusiness||!approvedBy||cp.id!==s.checkpoint?.id||cp.businessId!==s.businessId||(!s.members.includes(identity().deviceId)&&cp.offers[identity().deviceId]!==s.pending?.offerId))throw Error('Invalid recovered-device enrollment confirmation.');s.checkpoint=await sealCheckpoint(cp);s.members=cp.members;s.recoveredDevice=false;s.status='Awaiting Other Device';s.pending=null;await write(()=>persist(s));return true})}
 function cashImpacts(t){if(!t)return {cash:0,posCash:0,posElectronic:0,bank:0,debt:0,payable:0};const c=calc([copy(t)],{openingCash:0,posOpeningCash:0,posOpeningElectronic:0,openingDebt:0,openingSupplierPayable:0});return {cash:c.expectedCash,posCash:c.pos.expectedCash,posElectronic:c.pos.expectedElectronic,bank:c.expectedBank,debt:c.closingDebtRaw,payable:c.closingPayableRaw};}
 let accountCache=null;
 function accountBalances(){if(!initialized||!state().checkpoint)return null;const cp=state().checkpoint,rev=RS.status().revision;if(accountCache?.revision===rev)return copy(accountCache.value);const base=cp.records,rows=flatten(currentSnapshot()),out={};for(const k of ['cash','posCash','posElectronic','bank','debt','payable'])out[k]=k==='bank'?0:Number(cp.accounts[k].amount);for(const key of new Set([...Object.keys(base),...Object.keys(rows)])){if(!key.startsWith('tx:'))continue;const a=cashImpacts(base[key]?.value),b=cashImpacts(rows[key]?.value);for(const k of Object.keys(out))out[k]=r2(out[k]+b[k]-a[k])}const opening=openingProjection(events(),cp,state().resolutions).out;for(const[k,v]of Object.entries(opening))out[k]=r2(out[k]+v);accountCache={revision:rev,value:copy(out)};return out}
 function applyBalances(r){if(!initialized||suppressed||!state().checkpoint||historical)return r;const a=accountBalances();if(a){r.expectedCash=a.cash;r.pos.expectedCash=a.posCash;r.pos.expectedElectronic=a.posElectronic;r.closingDebtRaw=a.debt;r.closingDebt=Math.max(0,a.debt);r.closingPayableRaw=a.payable;r.closingPayable=Math.max(0,a.payable);r.storeCash=a.cash+a.posCash}return r}
 function financialRows(rows){if(!initialized||!state().checkpoint)return rows;const cp=state().checkpoint;return rows.map(r=>{let prior=0;if(r.id.startsWith('tx:')){const t=cp.records[r.id]?.value;prior=t?finTxImpact(t):0}else if(r.id.startsWith('fin:'))prior=finPrivate?.syncBaselineEvents?.[r.id.slice(4)]||0;return {...r,k:r.k-prior}}).filter(r=>r.k!==0)}
 function legacyBankRows(){if(!initialized||!state().checkpoint||!finKey||!finPrivate)return [];const cp=state().checkpoint,out=[];for(const[k,v]of Object.entries(cp.records))if(k.startsWith('tx:')){const amount=finTxImpact(v.value);if(amount)out.push({id:k,date:v.date,amountK:amount,description:v.value.note||v.value.party||TYPES[v.value.type]?.label||v.value.type,source:'Sales / Market before reconciliation'})}for(const e of finPrivate.events||[]){const amount=finPrivate.syncBaselineEvents?.[e.id];if(amount)out.push({id:'fin:'+e.id,date:e.date||e.ts.slice(0,10),amountK:amount,description:e.reason||e.type,source:'Financial Desk before reconciliation'})}return out.sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id))}
 function renderLegacyFinancialHistory(limit=80){const el=$('syncLegacyBank');if(!el)return;el.classList.toggle('hidden',!initialized||!state().checkpoint||!finKey);if(el.classList.contains('hidden'))return;const rows=legacyBankRows();$('syncLegacyBankRows').innerHTML=rows.slice(0,limit).map(r=>'<div class="finTx"><div><span>'+esc(r.description)+'</span><small>'+esc(r.date)+' · preserved history</small></div><b>'+esc(finMoney(r.amountK))+'</b></div>').join('')||'<p class="small">No prior bank movements in the accepted historical records.</p>';$('syncLegacyBankMore').classList.toggle('hidden',rows.length<=limit);$('syncLegacyBankMore').onclick=()=>renderLegacyFinancialHistory(limit+80)}
 function financialAnchor(){return initialized&&state().checkpoint?finPrivate?.anchor?.amountK??null:null}
 function beforeBusiness(before,source){if(!initialized||suppressed||historical)return;context={source};const old=new Set(before.map(t=>t.id));if(source==='Market Desk')for(const t of tx){if(old.has(t.id))continue;if(activeAdvance&&['purchase_cash','supplier_pay_cash'].includes(t.type)&&t.paymentFunding!=='external'){const available=advanceBalance(activeAdvance);if(t.amount>available+.004)throw Error('Market advance is insufficient. Choose another funding source or record a new advance.');t.paymentFunding='external';t.marketAdvanceId=activeAdvance;const m=getMarketState(),p=m.marketPurchases.find(p=>p.id===t.marketGroupPurchaseId||p.id===t.supplierPurchaseId);if(p){p.marketAdvanceId=activeAdvance;if(!t.supplierPaymentId||t.id===p.initialPaymentId)p.initialPaymentFunding='external';const pay=p.payments?.find(p=>p.id===t.supplierPaymentId);if(pay){pay.paymentFunding='external';pay.marketAdvanceId=activeAdvance}setMarketState(m)}}if(receiveNow===false&&TYPES[t.type]?.cat==='purchase'&&t.productId&&t.qty>0&&!t.stockReceiptPending){if(!applyEffect(t,true,true))throw Error('Could not preserve pending stock receipt.');t.stockReceiptPending=true;}}
 }
 function rebuildStock(){if(!initialized||!state().checkpoint)return null;const previous=parsedJson(KEY.draft,null)?.tx||[],old=new Map(previous.map(t=>[t.id,t])),next=new Map(tx.map(t=>[t.id,t])),safety=copy(getStock());for(const id of new Set([...old.keys(),...next.keys()])){const a=old.get(id),b=next.get(id);if(equal(transactionValue(a),transactionValue(b)))continue;if(a&&stockEffect(a)!==0&&!applyEffect(copy(a),true,true)){setStock(safety);return false}if(b&&stockEffect(b)!==0&&!applyEffect(b,false,true)){setStock(safety);return false}}return true}
 function endBusiness(){context=null;accountCache=null;if(initialized&&state().checkpoint)render()}
 function allTransactions(){const rows=flatten(currentSnapshot());return Object.entries(rows).filter(([k])=>k.startsWith('tx:')).map(([,v])=>v.value)}
 function advanceBalance(id){let total=initialized&&state().checkpoint&&id==='baseline-advance:'+state().checkpoint.id?n(state().checkpoint.unallocatedMarketAdvance):0;for(const t of allTransactions()){if(t.marketAdvanceId!==id)continue;if(t.type==='market_advance')total+=t.amount;else if(t.type==='market_advance_return'||['purchase_cash','supplier_pay_cash'].includes(t.type))total-=t.amount}return r2(total)}
 async function advance(amount,reason){requireAuth();limit(amount,'Market advance');if(!(amount>0)||!reason)throw Error('Enter a positive amount and reason.');const id=uuid('advance');const ok=await inventoryCommit(()=>{tx.push({id:uid('t'),type:'market_advance',amount:Number(amount),qty:0,unitPrice:0,domain:'internal',refKind:'internal',marketAdvanceId:id,note:reason,ts:nowIso()});return true},'Smart Sync');if(ok!==true)throw Error('Advance was not saved.');render();return id}
 async function returnAdvance(id,amount,reason){requireAuth();limit(amount,'Advance return');if(!(amount>0)||amount>advanceBalance(id)||!reason)throw Error('Enter a valid return within the outstanding advance.');const ok=await inventoryCommit(()=>{tx.push({id:uid('t'),type:'market_advance_return',amount:Number(amount),qty:0,unitPrice:0,domain:'internal',refKind:'internal',marketAdvanceId:id,note:reason,ts:nowIso()});return true},'Smart Sync');if(ok!==true)throw Error('Return was not saved.');render()}
 async function receive(transactionId){requireAuth();const source=allTransactions().find(t=>t.id===transactionId);if(!source?.stockReceiptPending)throw Error('No pending stock receipt for this purchase.');const receiptId='receipt:'+transactionId;if(allTransactions().some(t=>t.id===receiptId))return false;const ok=await inventoryCommit(()=>{const t={...copy(source),id:receiptId,type:'adjust_plus',amount:0,unitPrice:0,costSnapshot:source.unitPrice,receiptSourceId:transactionId,stockReceiptPending:false,note:'Stock received · '+source.productName,ts:nowIso()};delete t.batchId;delete t.physicalPackBefore;delete t.batchAllocations;if(!applyEffect(t,false))throw Error('Receipt could not be applied.');tx.push(t);return true},'Stock receipt');if(ok!==true)throw Error('Receipt was not saved.');render();return true}
 function backup(){return initialized?{state:{...serializedState(state()),checkpoint:copy(state().checkpoint),pending:copy(state().pending),proposal:copy(state().proposal),pendingImport:copy(state().pendingImport)},events:copy(events())}:null}
 function validateBackup(b){if(b==null)return;if(b.state?.version!==1||!Array.isArray(b.events))throw Error('Backup synchronization metadata is damaged.');const ids=new Set();for(const e of b.events){if(!e?.id||ids.has(e.id)||e.id!==e.deviceId+':'+e.seq||!Number.isSafeInteger(e.seq))throw Error('Invalid or duplicate backup sync event.');ids.add(e.id)}if(b.state.checkpoint&&!b.state.members?.includes(identity()?.deviceId)){/* Recovered installations must enroll; never copy identity. */}}
 function restoreBackup(b){validateBackup(b);lock();const id=identity();suppressed++;queueMicrotask(()=>suppressed--);if(b){const s=copy(b.state);s.shadows={};for(const k of watched){const v=safeGet(k);s.shadows[k]=v==null?null:JSON.parse(v)}const sourceSeq=b.events.filter(e=>e.deviceId===id.deviceId).reduce((m,e)=>Math.max(m,e.seq),s.checkpoint?.cut?.[id.deviceId]||0);s.seq=Math.max(sourceSeq,id.highSequence||0);s.recoveryGaps=s.checkpoint?.members.includes(id.deviceId)&&s.seq>sourceSeq;s.originStartSeq=id.origins?.[s.businessId]||s.seq+1;storeSet(IDENTITY,JSON.stringify({...id,highSequence:s.seq,origins:{...id.origins,[s.businessId]:s.originStartSeq}}));s.lastConfirmed=null;s.peers={};s.pending=null;s.proposal=null;s.recovery=null;s.recoveredDevice=!!s.checkpoint&&!s.members.includes(id.deviceId);persist(s);RS.setCollection(EVENTS,copy(b.events));}else{const s=empty();s.shadows={};for(const k of watched){const v=safeGet(k);s.shadows[k]=v==null?null:JSON.parse(v)}persist(s);RS.setCollection(EVENTS,[])}accountCache=null;}
 function status(){if(!initialized)return {status:'Not Set Up',checkpointId:null};const s=state(),id=identity();let text=!s.checkpoint?(s.proposal?'Reconciliation Pending':s.pending?'Reconciliation Required':'Not Set Up'):s.recoveredDevice?'Reconciliation Required':s.recoveryGaps?'Recovery Needs Missing Updates':s.shortages?.length?'Merge Conflict':s.status||'Awaiting Other Device';if(text==='Synchronized to Confirmed Checkpoint'&&!s.members.filter(d=>d!==id.deviceId).every(d=>s.peers[d]?.known?.digest===s.lastConfirmed?.digest&&!s.peers[d]?.awaitingConfirmation))text='Awaiting Other Device';if(preview)text='Import Awaiting Review';return {status:text,deviceId:id.deviceId,label:id.label,businessId:s.businessId,checkpointId:s.checkpoint?.id||null,events:events().length,pendingLocal:events().filter(e=>e.deviceId===id.deviceId&&e.seq>(s.lastConfirmed?Math.max(0,...Object.values(s.peers).map(p=>p.known?.vector?.[id.deviceId]||0)):s.checkpoint?.cut[id.deviceId]||0)).length,lastConfirmed:s.lastConfirmed,members:s.members,shortages:s.shortages||[],recoveredDevice:s.recoveredDevice||false}}
