 const style=document.createElement('style');style.id='roseachy-smart-sync-style';style.textContent='.syncPanel{max-width:900px;width:min(96vw,900px);max-height:92dvh;overflow:auto}.syncPanel{background:var(--roseachy-input,var(--card))!important;color:var(--rs-input-fg,var(--text))!important}html body[data-theme] .syncPanel :is(h3,h4,p,label,summary,pre,td,th,b){color:var(--rs-input-fg,var(--text))!important;-webkit-text-fill-color:var(--rs-input-fg,var(--text))!important}.syncPanel pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;color:var(--text)}.syncPanel h3,.syncPanel h4,.syncPanel p,.syncPanel label{color:var(--text)}.syncPanel .small{color:var(--muted)}.syncPanel details{padding:10px;border:1px solid var(--line);border-radius:12px;margin:8px 0}.syncPanel summary{cursor:pointer;font-weight:700}.syncPanel button{margin:4px}.syncPanel input,.syncPanel select{max-width:100%}.syncTable{overflow-x:auto}.syncTable td input{min-width:90px;width:120px}.syncConflict{border:1px solid var(--line);padding:12px;margin:10px 0;border-radius:12px}.syncRow{display:flex;gap:10px;align-items:center;justify-content:space-between;padding:8px 0}.syncHeader{display:flex;align-items:center;justify-content:space-between;gap:10px}.syncWarning{padding:10px;border:1px solid var(--line);border-radius:10px}';document.head.appendChild(style);
 const entry=document.createElement('details');entry.className='settingsGroup';entry.id='smartSyncSettings';entry.innerHTML='<summary>Smart Sync & Merge</summary><div class="settingsBody"><p>Exchange missing business activities with another offline Roseachy device. First reconcile stock and balances; every device can contribute valid work.</p><button type="button" id="openSmartSyncSettings" class="primary">Open Smart Sync & Merge</button></div>';$('settingsDesk').appendChild(entry);
 const shortcut=document.createElement('button');shortcut.type='button';shortcut.id='openSmartSyncMarket';shortcut.className='ghost';shortcut.textContent='Smart Sync & Merge';$('marketDesk').prepend(shortcut);const financial=document.createElement('button');financial.id='openSmartSyncFinancial';financial.type='button';financial.textContent='Smart Sync & Merge';$('finMenu').appendChild(financial);
 const legacy=document.createElement('details');legacy.id='syncLegacyBank';legacy.className='hidden';legacy.innerHTML='<summary>Preserved bank history before reconciliation</summary><p class="small">These original movements remain available for audit. They are already included in the verified opening bank position and are not replayed. Original source anchors and reviews are retained; incomplete historical running balances need supervised review.</p><div id="syncLegacyBankRows"></div><button type="button" id="syncLegacyBankMore">Show more preserved movements</button><button type="button" id="syncLegacyBankCSV">Export preserved bank history CSV</button>';$('finHistoryPanel').appendChild(legacy);$('syncLegacyBankCSV').onclick=()=>{if(!finKey)return;const rows=[['Date','Description','Original movement NGN','Record ID','Source'],...legacyBankRows().map(r=>[r.date,r.description,finN(r.amountK).toFixed(2),r.id,r.source])];finDownloadBlob('\ufeff'+rows.map(r=>r.map(finCsvEscape).join(',')).join('\r\n'),'Roseachy-Preserved-Bank-History.csv','text/csv;charset=utf-8');toast('Historical bank CSV exported; keep this file private.')};
 const overlay=document.createElement('div');overlay.id='syncOverlay';overlay.className='marketOverlay hidden';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Smart Sync and Merge');overlay.innerHTML=`<div class="marketPanel syncPanel"><div class="syncHeader"><h3>Smart Sync & Merge</h3><button id="syncClose" type="button" class="ghost">Close & Lock</button></div><p id="syncStatus" class="small"></p><p id="syncIdentity" class="small"></p><p id="syncConfirmed" class="small"></p><p id="syncMessage" role="status" aria-live="polite"></p><div id="syncGate"><p>Use your existing Financial Desk PIN to authorize a protected sync session. Device PINs stay local.</p><label>Financial PIN<input id="syncPin" type="password" inputmode="numeric" autocomplete="off" maxlength="4"></label><button id="syncAuthorize" class="primary" type="button">Authorize synchronization</button><button id="syncGoFinancial" type="button">Set up / recover Financial access</button></div><div id="syncPanel" class="hidden"><label>Device label<input id="syncLabel" maxlength="80"></label><button id="syncSaveLabel" type="button">Save label</button><label>Shared sync passphrase<input id="syncPhrase" type="password" autocomplete="off" minlength="12"></label><p class="small">Use at least 12 characters, separate from Financial PINs. Share it securely with the intended business devices; it authenticates and encrypts files offline. No account or internet is required.</p><details open><summary>First-time reconciliation / device enrollment</summary><p>1. Export Full Backup and keep it outside the app. 2. Select the saved file below to verify recovery. Both phones must do this. 3. Exchange reconciliation offers and approve the shared starting position. 4. Send the checkpoint back and exchange acknowledgements.</p><button id="syncRecoveryDownload" type="button">Export recovery Full Backup</button><label>Read back saved Full Backup<input id="syncRecoveryFile" type="file" accept=".json,application/json"></label><p id="syncRecoveryStatus" class="small">Recovery backup not yet verified.</p><label><input type="checkbox" id="syncSameBusiness"> I verified that these devices represent the same business.</label><label><input type="checkbox" id="syncSnapshotScope"> Verified opening quantities and balances refer to the captured recovery snapshots; later activities must be applied separately.</label><label>Responsible person<input id="syncApprover" maxlength="100"></label><label>Stock verification source<select id="syncStockSource"><option value="physical-count">Physical stock count</option><option value="verified-history">Verified transaction reconstruction</option></select></label><label>Stock count / discrepancy explanation<input id="syncStockReason" maxlength="1000"></label><label>Account verification source<input id="syncAccountSource" placeholder="Cash count, bank statement, supplier/customer review"></label><label>Financial discrepancy explanation<input id="syncAccountReason" maxlength="1000"></label><button id="syncExportOffer" type="button">Export reconciliation offer</button><button id="syncExportCheckpoint" type="button">Export approved checkpoint again</button></details><div><label>Receiving device<select id="syncRecipient"></select></label><button id="syncExportUpdates" type="button" class="primary">Export Updates</button><button id="syncImportButton" type="button" class="primary">Import & Merge</button><input id="syncImportFile" type="file" class="hidden" accept=".json,application/json"><button id="syncExportAck" type="button">Export acknowledgement</button><button id="syncResumeImport" type="button">Resume saved import</button></div><div id="syncReview"></div><details><summary>Market advances & stock receipts</summary><p class="small">An advance moves business cash into purchasing funds. Purchases charged to it do not deduct Retail cash again. Goods awaiting receipt remain unavailable until recorded as received.</p><label>Advance amount<input id="syncAdvanceAmount" type="number" min="0" step=".01"></label><label>Reason / market worker<input id="syncAdvanceReason"></label><button id="syncAdvanceCreate" type="button">Record cash advance</button><label>Funding for the next Market cash purchases<select id="syncAdvanceSelect"></select></label><label>Unspent amount returned<input id="syncAdvanceReturn" type="number" min="0" step=".01"></label><button id="syncAdvanceReturnSave" type="button">Return unspent advance</button><label><input type="checkbox" id="syncReceiveNow" checked> Purchased stock is physically received immediately</label><div id="syncReceipts"></div></details><details><summary>Permanent movement & amendment history</summary><div id="syncHistory"></div><button id="syncExportArchive" type="button">Export reconciliation archive</button></details><p class="syncWarning small">Sync merges activities; Full Backup restores a prior state. They are separate operations. A file export does not prove receipt. Keep external recovery copies and confirm exchanges on every participating device.</p></div></div>`;document.body.appendChild(overlay);
 for(const id of ['openSmartSyncSettings','openSmartSyncMarket','openSmartSyncFinancial'])$(id).onclick=open;$('syncClose').onclick=()=>{if(busy)return showToast('A protected sync save is finishing. Wait before closing.');overlay.classList.add('hidden');lock()};overlay.addEventListener('click',e=>{if(e.target===overlay){overlay.classList.add('hidden');lock()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)lock()});new MutationObserver(()=>{if(overlay.classList.contains('hidden'))lock()}).observe(overlay,{attributes:true,attributeFilter:['class']});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!overlay.classList.contains('hidden')){overlay.classList.add('hidden');lock()}});
 $('syncAuthorize').onclick=()=>action(async()=>{await authenticate($('syncPin').value);$('syncPin').value='';$('syncGate').classList.add('hidden');$('syncPanel').classList.remove('hidden');$('syncMessage').textContent='Authorized for five minutes. Financial PINs are not exported.'});$('syncGoFinancial').onclick=()=>{overlay.classList.add('hidden');lock();switchDesk('financial')};$('syncSaveLabel').onclick=()=>action(()=>api.setLabel($('syncLabel').value));
 $('syncRecoveryDownload').onclick=()=>action(()=>guard(async()=>{const backup=await roseachySafeBackup(),result=await saveFile(backup,'Roseachy-Recovery-Full-Backup.json');await roseachyBackupRecorded(result==='android'?'picker':result);$('syncMessage').textContent='Recovery file saved/downloaded. Select that file below to verify it before enrollment.'}));$('syncRecoveryFile').onchange=()=>action(async()=>{const f=$('syncRecoveryFile').files[0];if(!f)return;if(f.size>32*1024*1024)throw Error('Backup is too large.');const result=await verifyRecovery(await f.text());$('syncRecoveryStatus').textContent='Verified readable recovery backup: '+result.hash.slice(0,16)+'…';$('syncRecoveryFile').value=''});
 $('syncExportOffer').onclick=()=>action(async()=>{if(!$('syncSameBusiness').checked)throw Error('Confirm shared business identity before pairing.');await saveFile(await offer(checkPhrase()),'Roseachy-Reconciliation-Offer.json')});$('syncImportButton').onclick=()=>$('syncImportFile').click();$('syncImportFile').onchange=()=>action(async()=>{await importFile($('syncImportFile').files[0]);$('syncImportFile').value=''});
 $('syncExportCheckpoint').onclick=()=>action(async()=>{const cp=proposal||(state().proposal?await openCheckpoint(state().proposal):state().checkpoint?await openCheckpoint(state().checkpoint):null);if(!cp)throw Error('No approved checkpoint exists yet.');await saveFile(await checkpointPackage(cp,checkPhrase()),'Roseachy-Reconciliation-Checkpoint.json')});$('syncExportUpdates').onclick=()=>action(async()=>{await saveFile(await updates(checkPhrase(),$('syncRecipient').value||null),'Roseachy-Smart-Sync-Updates.json')});$('syncExportAck').onclick=()=>action(async()=>{await saveFile(await acknowledgement(checkPhrase()),'Roseachy-Smart-Sync-Acknowledgement.json')});
